<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Core/PublicPage.php';require dirname(__DIR__).'/app/Core/Database.php';$rows=[];$error=null;
try{$db=Database::connection();$q=$db->query("SELECT service_name,description,requirements_text,fee_text,processing_time_text,service_channel FROM citizen_charter_services WHERE status='PUBLISHED' ORDER BY service_name");$rows=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log('Charter page: '.$e->getMessage());$error='Citizen’s Charter information is unavailable.';}
pageHeader('Citizen’s Charter','Service descriptions, requirements, fees, and processing information.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">SERVICE STANDARDS</p><h1>Citizen’s Charter</h1><p>Review the service information published by Barangay San Antonio.</p></div></section><section class="section"><div class="notice warning"><b>Official details require confirmation</b><p>Fees, processing times, requirements, and service commitments must be approved by the Barangay and aligned with its current Citizen’s Charter. Do not rely on unpublished or draft values.</p></div><?php if($error): ?><div class="notice warning"><?= Security::e($error) ?></div><?php elseif(!$rows): ?><div class="publication-empty"><h2>Charter entries are being prepared</h2><p>No service charter entries have been formally published in this demonstration installation. Please contact the Barangay Hall for current requirements, fees, and processing times.</p></div><?php else: ?><div class="civic-grid"><?php foreach($rows as $r): ?><article class="civic-card"><h2><?= Security::e($r['service_name']) ?></h2><p><?= Security::e($r['description']??'') ?></p><p><b>Requirements</b><br><?= nl2br(Security::e($r['requirements_text']??'To be confirmed')) ?></p><p><b>Fees</b><br><?= Security::e($r['fee_text']) ?></p><p><b>Processing time</b><br><?= Security::e($r['processing_time_text']) ?></p><p><b>Channel</b><br><?= Security::e($r['service_channel']??'Contact the Barangay Hall') ?></p></article><?php endforeach; ?></div><?php endif; ?></section></main><?php pageFooter();
